-- Migration 0008 — Phase 6: the §10.2 number-sequence counter table.
-- Only `invoice_sequences` is created here: the order-number generator
-- (§9.8) uses the same sequence mechanism with its own scope
-- ('ORDER:<year>'), so the table must exist before checkout can issue
-- order numbers. `invoices` (§10.1) and the template tables (§10.3)
-- land in Phase 7.
-- Generated by drizzle-kit from src/database/schema/invoices.ts and
-- hand-adjusted per DATABASE_DESIGN.md §13.1:
--   1. The CREATE TABLE carries the design §2.1 table options
--      ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci.
--   2. drizzle-kit also emitted DROP/re-ADD statements for the three
--      circular pages ↔ page_revisions FKs under auto-generated names,
--      plus a DROP of the hand-written FULLTEXT index ft_news_search:
--      the known phantom diffs (see 0005's header). All of them were
--      removed here, and the design FK names / ft_news_search were
--      restored in meta/0008_snapshot.json. A future `db:generate` may
--      re-emit those phantom diffs — remove them the same way.
CREATE TABLE `invoice_sequences` (
	`scope` varchar(40) NOT NULL,
	`last_value` bigint unsigned NOT NULL DEFAULT 0,
	`updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	CONSTRAINT `invoice_sequences_scope` PRIMARY KEY(`scope`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
